# The helpers documented with `@eval standalone_indiedown_export()`
# are exported from template packages, but stay internal in indiedown.
standalone_indiedown_export <- function() {
  if (identical(utils::packageName(), "indiedown")) "@noRd" else "@export"
}

indiedown_pdf_document_with_asset <- function(includes = NULL, ...) {
  # file preamble
  if (file.exists(file.path(indiedown_path(), "preamble.tex"))) {
    file_preamble <- tempfile(fileext = ".tex")
    txt <- readLines(
      file.path(indiedown_path(), "preamble.tex"),
      encoding = "UTF-8"
    )
    txt <- gsub("<<indiedown_path>>", indiedown_path_tex(), txt, fixed = TRUE)
    writeLines(txt, file_preamble)

    if (is.null(includes)) {
      includes <- rmarkdown::includes(in_header = file_preamble)
    } else {
      if ("in_header" %in% names(includes)) {
        warning(
          "The use of 'includes, in_header' overwrites preamble.tex from asset and may mess up the layout."
        )
      } else {
        includes$in_header <- file_preamble
      }
    }
  }

  ans <- rmarkdown::pdf_document(includes = includes, ...)

  # use pre_processor from asset package or pre_processor_basic, if not present
  file_pre_processor <- file.path(indiedown_path(), "pre_processor.R")
  if (file.exists(file_pre_processor)) {
    env <- environment()
    source(file.path(file_pre_processor), env)
    stopifnot(exists("pre_processor", envir = env))
  } else {
    pre_processor <- pre_processor_basic
  }

  ans$pre_processor <- pre_processor
  repeat_font_message(ans)
}

# The message about a missing font is shown when the pre-processor runs,
# where the log of LaTeX scrolls it away.
# If the render writes the output, the message is shown again
# when rmarkdown::render() exits, after the "Output created" line,
# also when knitting in RStudio, which renders in a separate R session.
repeat_font_message <- function(format) {
  state <- new.env(parent = emptyenv())

  pre_processor <- format$pre_processor
  format$pre_processor <- function(...) {
    state$shown <- NULL
    withCallingHandlers(
      pre_processor(...),
      indiedown_font_message = function(m) state$shown <- m
    )
  }

  # runs only after the output is written
  post_processor <- format$post_processor
  format$post_processor <- function(metadata, input_file, output_file, ...) {
    if (!is.null(post_processor)) {
      output_file <- post_processor(metadata, input_file, output_file, ...)
    }
    state$written <- state$shown
    output_file
  }

  on_exit <- format$on_exit
  format$on_exit <- function() {
    if (is.function(on_exit)) {
      on_exit()
    }
    shown <- state$written
    state$shown <- NULL
    state$written <- NULL
    if (!is.null(shown)) {
      message(shown)
    }
  }

  format
}

pre_processor_basic <- function(
  metadata,
  input_file,
  runtime,
  knit_meta,
  files_dir,
  output_dir
) {
  args <- apply_default_yaml(metadata = metadata)
}

apply_default_yaml <- function(metadata) {
  defaults_txt <- readLines(
    file.path(indiedown_path(), "default.yaml"),
    encoding = "UTF-8"
  )

  # replace <<indiedown_path>> by package path
  defaults_txt <- gsub(
    "<<indiedown_path>>",
    indiedown_path_tex(),
    defaults_txt,
    fixed = TRUE
  )

  defaults <- yaml::yaml.load(defaults_txt)

  # the main font is resolved separately, also if set in the document
  fonts <- resolve_fonts(metadata, defaults)
  defaults[c(
    "mainfont",
    "mainfontoptions",
    "preferredmainfont",
    "preferredmainfontoptions"
  )] <- NULL

  # do not apply asset defaults if variable set in document
  defaults_applied <- defaults[setdiff(names(defaults), names(metadata))]

  # pandoc variables take precedence over the document's metadata
  args <- list_to_pandoc_args(c(defaults_applied, fonts))

  # pandoc ignores 'header-includes' if includes$in_header is specified
  # https://github.com/jgm/pandoc/issues/3139
  # we can still use `header-includes` by passing it as a command line option to pandoc
  if (!is.null(rmarkdown::metadata$`header-includes`)) {
    args <- c(
      args,
      "--variable",
      paste0(
        "header-includes:",
        paste(rmarkdown::metadata$`header-includes`, collapse = "\n")
      )
    )
  }

  args
}

# The main font is the first of:
#
# 1. the font named in the `mainfont` field of the document,
#    or else in the option `<package>.mainfont`, if it is installed;
#    it can be a font file, as a path or as a file name in the TeX tree,
#    or the name of a system font;
# 2. the preferred font of the format, `preferredmainfont` in default.yaml,
#    with `preferredmainfontoptions`, if it is installed:
#    typically a licensed or corporate font that cannot be shipped;
# 3. the fallback font, `mainfont` in default.yaml, with `mainfontoptions`:
#    typically font files shipped in inst/indiedown/fonts and loaded by path.
#
# The preferred font counts as installed only if all fonts that it names,
# in `preferredmainfont` and in options such as `BoldFont=`, are found.
# If their font files are found in one folder, see `find_font_files()`,
# the preferred font is loaded from them by path, like the fallback font,
# because LaTeX may not find an installed font by name,
# such as a font installed for the current user on Windows.
# Otherwise, it is loaded by name if the system fonts include all its fonts.
# A font named in the document or in the option is loaded by name
# if the system fonts include it, and from its font files if only these are found.
# The option `<package>.font_path` names a folder with font files,
# searched first, for users who cannot install fonts.
# If the system fonts cannot be looked up, a named font is left to LaTeX,
# and the fallback font replaces the preferred one unless its files are found.
# For a missing font, a message explains how to install fonts,
# once per session;
# the output format repeats it at the end of the render.
# The `mainfontoptions` of the document are used with a named font
# and appended to those of the preferred or fallback font otherwise.
#
# Returns a list with the pandoc variables `mainfont` and `mainfontoptions`,
# omitting unset ones.
resolve_fonts <- function(
  metadata,
  defaults,
  mainfont = get_indiedown_option("mainfont"),
  font_path = get_indiedown_option("font_path")
) {
  options <- unlist(metadata[["mainfontoptions"]])

  font <- metadata[["mainfont"]]
  origin <- " from the `mainfont` field of the document"
  if (is.null(font)) {
    font <- mainfont
    origin <- paste0(
      " from the `",
      indiedown_option_name("mainfont"),
      "` option"
    )
  }

  # the start of the message about a missing font and how to install it
  missing <- NULL
  if (!is.null(font)) {
    named <- Filter(
      Negate(is.null),
      list(mainfont = font, mainfontoptions = options)
    )
    if (is.null(defaults[["mainfont"]]) || !isFALSE(fonts_installed(font))) {
      return(named)
    }
    files <- find_font_files(font_faces(font, options), font_path)
    if (!is.null(files)) {
      return(font_from_files(named, files))
    }
    missing <- c(
      paste0("Font \"", font, "\"", origin, " was not found"),
      font_install_hint(font)
    )
    # the options were meant for the missing font
    options <- NULL
  }

  fonts <- list(
    mainfont = defaults[["mainfont"]],
    mainfontoptions = unlist(defaults[["mainfontoptions"]])
  )
  preferred <- list(
    mainfont = defaults[["preferredmainfont"]],
    mainfontoptions = unlist(defaults[["preferredmainfontoptions"]])
  )
  if (!is.null(preferred$mainfont)) {
    faces <- font_faces(preferred$mainfont, preferred$mainfontoptions)
    files <- find_font_files(faces, font_path)
    if (!is.null(files)) {
      fonts <- font_from_files(preferred, files)
    } else if (isTRUE(all(fonts_installed(faces)))) {
      fonts <- preferred
    } else if (is.null(missing)) {
      missing <- preferred_font_missing(preferred$mainfont, font_path)
    }
  }

  if (!is.null(missing) && is.null(font_messages[[missing[[1]]]])) {
    font_messages[[missing[[1]]]] <- TRUE
    text <- paste0(
      missing[[1]],
      ", using \"",
      fonts$mainfont,
      "\" instead.\n",
      "To use it, ",
      missing[[2]],
      ".\n"
    )
    message(structure(
      class = c("indiedown_font_message", "message", "condition"),
      list(message = text, call = NULL)
    ))
  }

  fonts$mainfontoptions <- c(fonts$mainfontoptions, options)
  Filter(Negate(is.null), fonts)
}

# The value of the option `<package>.<name>`,
# where `<package>` is the package that holds this file, such as `mydown`,
# or `default` if the option is not set.
# This is how a template package reads its options,
# e.g. `font_path = get_indiedown_option("font_path")` in a function signature.
get_indiedown_option <- function(name, default = NULL) {
  getOption(indiedown_option_name(name), default)
}

# The name of the option `<package>.<name>`, as users set it.
# The package is the one that holds this file, found from `env`.
# Where this file is not part of a package, such as when it is sourced,
# or `env` is the global environment, the package is taken to be `indiedown`.
indiedown_option_name <- function(
  name,
  env = environment(indiedown_option_name)
) {
  package <- utils::packageName(env)
  paste0(if (is.null(package)) "indiedown" else package, ".", name)
}

# missing fonts reported in this session
font_messages <- new.env(parent = emptyenv())

# The start of the message about the missing preferred font,
# and how to make it available
preferred_font_missing <- function(font, font_path) {
  path_option <- indiedown_option_name("font_path")
  hint <- if (!is.null(font_path)) {
    paste0(
      "check that the folder \"",
      paste(font_path, collapse = "\", \""),
      "\" from the option `",
      path_option,
      "` holds its font files"
    )
  } else {
    paste0(
      font_install_hint(font),
      ",\nor set `options(",
      path_option,
      " = \"<folder>\")` to a folder with its font files"
    )
  }
  c(paste0("Preferred font \"", font, "\" was not found"), hint)
}

# The font and the fonts that its fontspec options name for other faces,
# such as `BoldFont=`, where `*` stands for the font, as in fontspec
font_faces <- function(font, options) {
  pattern <- "^[[:alpha:]]+Font="
  faces <- sub(pattern, "", grep(pattern, options, value = TRUE))
  unique(c(font, gsub("*", font, faces, fixed = TRUE)))
}

# The pandoc variables that load `font`, a list with `mainfont`
# and `mainfontoptions`, from its font `files`, named by face as in
# `font_faces()`: with `Path=` and file names, like the fallback font
font_from_files <- function(font, files) {
  pattern <- "^([[:alpha:]]+Font=)(.*)$"
  options <- as.character(font$mainfontoptions)
  is_face <- grepl(pattern, options)
  faces <- sub(pattern, "\\2", options[is_face])
  faces <- gsub("*", font$mainfont, faces, fixed = TRUE)
  keys <- sub(pattern, "\\1", options[is_face])
  options[is_face] <- paste0(keys, basename(files[faces]))
  list(
    mainfont = basename(files[[font$mainfont]]),
    mainfontoptions = c(
      paste0("Path=", sanitize_tex(dirname(files[[1]])), "/"),
      options
    )
  )
}

# The font files of `faces`, one for each, all in the same folder,
# named by face, or NULL if they are not found.
# The folder `font_path` and the folders of the fonts installed
# for the current user are searched by file name and by PostScript name,
# the folders of the fonts installed for all users by file name,
# and then the installed fonts that `installed_fonts()` lists,
# by PostScript name and full name.
find_font_files <- function(
  faces,
  font_path = get_indiedown_option("font_path")
) {
  dirs <- font_dirs()
  for (dir in c(font_path, dirs$user, dirs$system)) {
    files <- list_font_files(normalizePath(dir, "/", mustWork = FALSE))
    stems <- sub("[.][^.]*$", "", basename(files))
    found <- match_font_files(faces, files, stems)
    if (is.null(found) && !(dir %in% dirs$system)) {
      found <- match_font_files(faces, files, font_postscript_names(files))
    }
    if (!is.null(found)) {
      return(found)
    }
  }
  fonts <- installed_fonts()
  match_font_files(faces, fonts$path, fonts$name)
}

# The `.otf` and `.ttf` files in `dir` and its subfolders,
# down to `depth` levels and at most `limit` files,
# so that large font collections are searched in bounded time.
list_font_files <- function(dir, depth = 3, limit = 5000) {
  files <- list.files(
    dir,
    "[.](otf|ttf)$",
    full.names = TRUE,
    ignore.case = TRUE
  )
  if (depth > 0) {
    for (subdir in list.dirs(dir, recursive = FALSE)) {
      if (length(files) >= limit) {
        break
      }
      files <- c(files, list_font_files(subdir, depth - 1, limit))
    }
  }
  utils::head(files, limit)
}

# The folders of the fonts installed for the current user and for all users,
# where fc-list may not see them.
# TeX Live's fontconfig on Windows, which XeTeX and fc-list use,
# only sees the fonts installed for all users.
# On Linux, the folders are those that fontconfig reads,
# so that fonts are found also where `fc-list` is not installed,
# as in minimal containers.
font_dirs <- function(sysname = Sys.info()[["sysname"]]) {
  switch(
    sysname,
    Windows = list(
      user = file.path(Sys.getenv("LOCALAPPDATA"), "Microsoft/Windows/Fonts"),
      system = file.path(Sys.getenv("WINDIR"), "Fonts")
    ),
    Darwin = list(user = "~/Library/Fonts", system = "/Library/Fonts"),
    list(
      user = c(
        "~/.local/share/fonts",
        "~/.fonts",
        if (nzchar(Sys.getenv("XDG_DATA_HOME"))) {
          file.path(Sys.getenv("XDG_DATA_HOME"), "fonts")
        }
      ),
      system = c("/usr/local/share/fonts", "/usr/share/fonts")
    )
  )
}

# The first files, by folder, whose `font_names` match `faces`:
# one file for each face, all in the same folder, named by face, or NULL.
# Font collections are skipped, because fontspec would need the index.
match_font_files <- function(faces, paths, font_names) {
  if (is.null(font_names)) {
    return(NULL)
  }
  keep <- grepl("[.](otf|ttf)$", paths, ignore.case = TRUE)
  paths <- paths[keep]
  font_names <- tolower(font_names[keep])
  for (dir in unique(dirname(paths))) {
    in_dir <- dirname(paths) == dir
    files <- paths[in_dir][match(tolower(faces), font_names[in_dir])]
    if (!anyNA(files) && !anyDuplicated(files)) {
      names(files) <- faces
      return(files)
    }
  }
  NULL
}

# The PostScript names of font files, NA where they cannot be read,
# or NULL without the systemfonts package
font_postscript_names <- function(files) {
  if (!requireNamespace("systemfonts", quietly = TRUE)) {
    return(NULL)
  }
  vapply(
    files,
    function(file) {
      tryCatch(
        systemfonts::font_info(path = file)$name[[1]],
        error = function(e) NA_character_
      )
    },
    character(1),
    USE.NAMES = FALSE
  )
}

# TRUE for each installed font, FALSE for a missing one
fonts_installed <- function(fonts) {
  is_file <- is_font_file(fonts)
  installed <- rep(NA, length(fonts))
  installed[is_file] <- vapply(fonts[is_file], font_file_installed, logical(1))
  if (!all(is_file)) {
    installed[!is_file] <- tolower(fonts[!is_file]) %in%
      tolower(installed_font_names())
  }
  installed
}

font_file_installed <- function(font) {
  if (file.exists(font)) {
    return(TRUE)
  }
  if (basename(font) != font) {
    return(FALSE)
  }
  # a file name: look it up in the TeX tree
  kpsewhich <- Sys.which("kpsewhich")
  if (!nzchar(kpsewhich)) {
    return(NA)
  }
  found <- suppressWarnings(
    system2(kpsewhich, shQuote(font), stdout = TRUE, stderr = FALSE)
  )
  length(found) > 0
}

is_font_file <- function(font) {
  grepl("[.](otf|ttf|otc|ttc)$", font, ignore.case = TRUE)
}

# The installed system fonts, as a list with the `path` of each font file
# and its PostScript and full `name`s, both repeated as needed,
# and the `family` names of all fonts.
# fc-list lists the fonts that fontconfig finds,
# where XeTeX and LuaTeX look for system fonts on Linux
# and with TeX Live on Windows.
# It runs as a new process, so it sees the current FONTCONFIG_FILE,
# which tests can set to hide the system fonts.
# systemfonts covers systems without fc-list, such as macOS;
# it reads the font list only once per session,
# and it is required in that case: without it, this fails with an error.
installed_fonts <- function() {
  fc_list <- Sys.which("fc-list")
  if (nzchar(fc_list)) {
    out <- suppressWarnings(system2(
      fc_list,
      c(
        "--format",
        shQuote("%{file}\\t%{postscriptname}\\t%{fullname}\\t%{family}\\n")
      ),
      stdout = TRUE,
      stderr = FALSE
    ))
    fields <- lapply(strsplit(out, "\t", fixed = TRUE), function(x) {
      c(x, character(4))[1:4]
    })
    split_names <- function(x) trimws(unlist(strsplit(x, ",", fixed = TRUE)))
    font_names <- lapply(fields, function(x) split_names(x[2:3]))
    return(list(
      path = rep(vapply(fields, `[[`, "", 1), lengths(font_names)),
      name = as.character(unlist(font_names)),
      family = as.character(split_names(vapply(fields, `[[`, "", 4)))
    ))
  }

  rlang::check_installed(
    "systemfonts",
    "to look up installed fonts when `fc-list` is not available."
  )
  fonts <- systemfonts::system_fonts()
  list(path = fonts$path, name = fonts$name, family = fonts$family)
}

# Family, full and PostScript names of the installed system fonts
installed_font_names <- function() {
  fonts <- installed_fonts()
  c(fonts$family, fonts$name)
}

font_install_hint <- function(font, sysname = Sys.info()[["sysname"]]) {
  if (is_font_file(font)) {
    return(
      "check the path, relative paths start at the directory of the document"
    )
  }
  switch(
    sysname,
    Windows = paste(
      "install its font files for the current user",
      "(Settings > Personalization > Fonts, or right-click > Install)"
    ),
    Darwin = "open its font files and click \"Install\" in Font Book",
    "copy its font files to ~/.local/share/fonts"
  )
}

# list <- list(
#   indent = TRUE,
#   `compact-title` = TRUE,
#   classoption = c("twocolumn", "landscape")
# )
# list_to_pandoc_args(list)
list_to_pandoc_args <- function(list) {
  is_logical <- vapply(list, is.logical, TRUE)
  is_character <- vapply(list, is.character, TRUE)

  # prepare logicals (TRUE FALSE to yes no)
  list[is_logical] <- lapply(list[is_logical], function(x) {
    ifelse(x, "yes", "no")
  })
  # prepare character (comma separate multiple values)
  list[is_character] <- lapply(list[is_character], paste, collapse = ",")

  vars <- paste0(names(list), ":", unlist(list))

  zip <- function(x, y) {
    x <- rep_len(x, length(y))
    m <- matrix(c(x, y), nrow = 2, byrow = TRUE)
    as.vector(m)
  }
  zip("--variable", vars)
}

#' Path helpers
#'
#' `indiedown_path()` creates a path to this package's indiedown assets,
#' located at `inst/indiedown`.
#'
#' @param ... Path components, passed on to `system.file()`.
#' @return Character string, path to this package's indiedown assets
#' @examples
#' indiedown_path()
#' @eval standalone_indiedown_export()
indiedown_path <- function(...) {
  system.file("indiedown", ..., package = utils::packageName())
}

#' Path to indiedown assets, usable in LaTeX
#'
#' `indiedown_path_tex()` creates a path that is usable in LaTeX,
#' with all special characters escaped.
#'
#' @rdname indiedown_path
#' @eval standalone_indiedown_export()
indiedown_path_tex <- function(...) {
  sanitize_tex(indiedown_path(...))
}


sanitize_tex <- function(path) {
  # on win, tex does not like \\
  path <- gsub("\\", "/", fixed = TRUE, path)
  path <- gsub("~", "\\string~", path, fixed = TRUE)
  path
}

#' Glue LaTeX Code for Use in R Markdown
#'
#' Use the function to wrap literal LaTeX code in R. Use a raw string input
#' (`r"()"`) to automatically escape quotes and backslashes, as they are common
#' in LaTeX. Expressions enclosed by `<<` and `>>` will be evaluated as R code.
#'
#' `indiedown_glue()` uses a different default than the underlying
#' `glue::glue()` (`<<` and `>>`), because braces are so common in LaTeX.
#' Doubling the full delimiter (`<<<<` and `>>>>`) escapes it.
#'
#' @param x Character, often as a raw string (`r"()"`)
#' @param .open,.close The opening and closing delimiter.
#' @return Object of class `"knit_asis"` (so that knitr will treat it as is). Usually LaTeX code.
#' @eval standalone_indiedown_export()
#' @examples
#' x <- "something"
#' indiedown_glue(r"(\LaTeX\ code with <<x>> substituted )")
#'
indiedown_glue <- function(x, .open = "<<", .close = ">>") {
  ans <- glue::glue(x, .envir = sys.frame(-1), .open = .open, .close = .close)
  knitr::asis_output(ans)
}


# compatible with older versions. We can use raw strings from 4.0 on.
read_tex <- function(file) {
  paste(
    readLines(indiedown_path("tex", file), encoding = "UTF-8"),
    collapse = "\n"
  )
}

#' Set Default Value
#'
#' Set default value of an argument. If `x` is `NULL`, `default` is used.
#'
#' @param x Character string, or `NULL`
#' @param default If `x` is `NULL`, `default` is used.
#'
#' @return Character string
#' @examples
#' default(NULL)
#' default(NULL, "my default")
#' default("a string", "my default")
#' @eval standalone_indiedown_export()
default <- function(x, default = "") {
  ans <- if (is.null(x)) default else x
  force(ans)
}

# nocov end

# Snapshots of rendered PDF documents ------------------------------------------

# `expect_pdf_snapshot(name, rmd, ..., tolerance, dpi, system_fonts, fonts)`
# renders an R Markdown document to PDF,
# rasterizes each page to PNG with poppler via the pdftools package,
# and compares each page with its snapshot
# using `testthat::expect_snapshot_file()`.
# Use it in the tests of a template package
# to catch unintended changes to the rendered pages,
# such as fonts, margins, title pages, or the placement of floats.
#
# `skip_if_no_pdf_snapshot()` skips the current test
# where PDF snapshots cannot be taken:
# on CRAN, on systems other than Linux,
# and without rmarkdown, pdftools, callr, pandoc, or LaTeX.
# `expect_pdf_snapshot()` calls it before rendering.
#
# Arguments:
# * `name`: Prefix of the snapshot file names, unique within a test file.
# * `rmd`: The lines of the R Markdown document, a character vector.
#   It is rendered in a temporary directory,
#   in a new environment whose parent is the global environment.
# * `...`: These dots are for future extensions and must be empty.
# * `tolerance`: The share of pixels, between 0 and 1,
#   that may differ between a page and its snapshot.
#   The default, 0, requires the PNG files to be byte-identical.
#   A positive value needs the png package.
# * `dpi`: Resolution of the rasterized pages, in dots per inch.
# * `system_fonts`: If `FALSE`, the default,
#   fontconfig sees only the fonts in `fonts`, or the fallback.
#   If `TRUE`, it sees the fonts installed on the system.
# * `fonts`: Directory with the fonts that the template bundles.
#   The default, `NULL`, uses `inst/indiedown/fonts` of the template package.
#
# `expect_pdf_snapshot()` returns `NULL`, invisibly.
# `skip_if_no_pdf_snapshot()` returns `TRUE`, invisibly, if it does not skip.
#
# ## Snapshot files
#
# For `name = "report"`, the snapshot directory of the test file holds
# `report-page-01.png`, `report-page-02.png`, and so on, one for each page,
# and `report-environment.txt`, a record of the toolchain.
# The record lists the versions of the operating system, R, pandoc, LaTeX,
# poppler, fontconfig, FreeType, and the R packages involved,
# the font that fontconfig offers for Helvetica,
# and a hash of each font file that the template bundles,
# or of the fallback fonts.
# The record never fails a test:
# it is written when the snapshot is created and kept as is afterwards.
# To refresh the snapshots and the record,
# delete the snapshot files of `name` and run the tests again.
#
# Pixel-exact comparisons are only stable on a fixed toolchain,
# so `skip_if_no_pdf_snapshot()` skips on systems other than Linux.
# A positive `tolerance` accepts small differences.
#
# testthat deletes the snapshot files that a complete test run does not use.
# When it skips or when rendering fails,
# `expect_pdf_snapshot()` declares the existing snapshot files of `name`
# with `testthat::announce_snapshot_file()`,
# so that a test run on a system without LaTeX keeps them.
#
# ## Fonts
#
# R's `grDevices::pdf()` device does not embed the fonts of a plot,
# it refers to Helvetica by name.
# poppler substitutes the font that fontconfig offers for Helvetica,
# so the rasterized plot text depends on the fonts installed on the system.
# Unless `system_fonts = TRUE`,
# `expect_pdf_snapshot()` therefore lets fontconfig see
# only the fonts that the template bundles in `fonts`
# while the document is rendered and rasterized.
# If the template bundles no fonts,
# Latin Modern Sans from the LaTeX installation is the fixed fallback.
# The pages are rasterized in a separate R process,
# because fontconfig reads its configuration only once per process.
#
# ## Example
#
# In `tests/testthat/test-visual.R` of a template package called mydown:
#
#   test_that("the report looks right", {
#     expect_pdf_snapshot(
#       "report",
#       c(
#         "---",
#         "title: Report",
#         "date: January 1, 2026",
#         "output: mydown::mydown",
#         "---",
#         "",
#         "Some text."
#       )
#     )
#   })
expect_pdf_snapshot <- function(
  name,
  rmd,
  ...,
  tolerance = 0,
  dpi = 100,
  system_fonts = FALSE,
  fonts = NULL
) {
  rlang::check_dots_empty()
  check_pdf_snapshot_args(name, rmd, tolerance, dpi, system_fonts, fonts)

  # Unless the snapshots are taken, declare the existing ones,
  # so that a complete test run does not delete them as unused.
  taken <- FALSE
  withr::defer(if (!taken) announce_pdf_snapshot(name))

  skip_if_no_pdf_snapshot()
  if (tolerance > 0) {
    rlang::check_installed("png", "to compare PDF snapshots with a tolerance.")
  }

  dir <- withr::local_tempdir()
  if (is.null(fonts)) {
    fonts <- indiedown_path("fonts")
  }
  if (!system_fonts) {
    fonts <- visible_fonts(fonts, dir)
    withr::local_envvar(FONTCONFIG_FILE = write_fonts_conf(fonts, dir))
  }

  input <- file.path(dir, paste0(name, ".Rmd"))
  writeLines(rmd, input)
  pdf <- rmarkdown::render(
    input,
    output_dir = dir,
    quiet = TRUE,
    envir = new.env(parent = globalenv())
  )

  pages <- rasterize_pdf(pdf, name, dpi)
  record <- paste0(name, "-environment.txt")
  writeLines(
    pdf_snapshot_environment(pdf, fonts, system_fonts),
    file.path(dir, record)
  )

  # Injecting the file name gives a readable label in failure messages
  compare <- compare_png(tolerance)
  for (page in pages) {
    rlang::inject(testthat::expect_snapshot_file(
      file.path(dir, !!page),
      compare = compare
    ))
  }
  rlang::inject(testthat::expect_snapshot_file(
    file.path(dir, !!record),
    compare = compare_true
  ))

  taken <- TRUE
  invisible()
}

skip_if_no_pdf_snapshot <- function() {
  testthat::skip_on_cran()
  if (!is_linux()) {
    testthat::skip("PDF snapshots are pixel-exact on Linux only")
  }
  testthat::skip_if_not_installed("rmarkdown")
  testthat::skip_if_not_installed("pdftools")
  testthat::skip_if_not_installed("callr")
  testthat::skip_if_not(
    rmarkdown::pandoc_available(),
    "pandoc is not available"
  )
  testthat::skip_if_not(has_latex(), "LaTeX is not available")
  invisible(TRUE)
}

check_pdf_snapshot_args <- function(
  name,
  rmd,
  tolerance,
  dpi,
  system_fonts,
  fonts,
  call = rlang::caller_env()
) {
  if (!rlang::is_string(name) || !nzchar(name)) {
    rlang::abort("`name` must be a non-empty string.", call = call)
  }
  if (!is.character(rmd)) {
    rlang::abort("`rmd` must be a character vector.", call = call)
  }
  if (!is_number(tolerance) || tolerance < 0 || tolerance > 1) {
    rlang::abort("`tolerance` must be a number between 0 and 1.", call = call)
  }
  if (!is_number(dpi) || dpi <= 0) {
    rlang::abort("`dpi` must be a positive number.", call = call)
  }
  if (!rlang::is_bool(system_fonts)) {
    rlang::abort("`system_fonts` must be `TRUE` or `FALSE`.", call = call)
  }
  if (!is.null(fonts) && !(rlang::is_string(fonts) && dir.exists(fonts))) {
    rlang::abort(
      "`fonts` must be the path to a directory or `NULL`.",
      call = call
    )
  }
}

is_number <- function(x) {
  is.numeric(x) && length(x) == 1 && !is.na(x)
}

is_linux <- function() {
  identical(tolower(Sys.info()[["sysname"]]), "linux")
}

has_latex <- function() {
  (rlang::is_installed("tinytex") && tinytex::is_tinytex()) ||
    any(nzchar(Sys.which(c("pdflatex", "xelatex", "lualatex"))))
}

announce_pdf_snapshot <- function(name) {
  if (!testthat::is_testing()) {
    return(invisible())
  }
  files <- unique(basename(list.files(
    testthat::test_path("_snaps"),
    recursive = TRUE
  )))
  prefix <- paste0(name, "-")
  rest <- substring(files, nchar(prefix) + 1)
  ours <- startsWith(files, prefix) &
    grepl("^(page-[0-9]+[.]png|environment[.]txt)$", rest)
  for (file in files[ours]) {
    testthat::announce_snapshot_file(file)
  }
  invisible()
}

font_files <- function(dir) {
  if (is.null(dir) || !dir.exists(dir)) {
    return(character())
  }
  files <- list.files(
    dir,
    pattern = "[.](otf|ttf|ttc|pfa|pfb)$",
    ignore.case = TRUE,
    recursive = TRUE
  )
  sort(files, method = "radix")
}

# The fallback is only added if the template bundles no fonts:
# next to the bundled fonts, fontconfig would offer it for some styles
# and mix two families in one plot.
visible_fonts <- function(fonts, dir) {
  if (length(font_files(fonts)) > 0) {
    return(fonts)
  }

  files <- paste0(
    "lmsans10-",
    c("regular", "bold", "oblique", "boldoblique"),
    ".otf"
  )
  paths <- run_command("kpsewhich", files)
  if (length(paths) != length(files)) {
    rlang::abort(c(
      "Can't find the fallback font Latin Modern Sans with `kpsewhich`.",
      i = paste(
        "Bundle fonts with the template in `inst/indiedown/fonts`,",
        "or set `system_fonts = TRUE`."
      )
    ))
  }

  fallback <- file.path(dir, "fonts-fallback")
  dir.create(fallback)
  file.copy(paths, fallback)
  fallback
}

write_fonts_conf <- function(fonts, dir) {
  conf <- file.path(dir, "fonts.conf")
  writeLines(
    c(
      "<?xml version=\"1.0\"?>",
      "<!DOCTYPE fontconfig SYSTEM \"fonts.dtd\">",
      "<fontconfig>",
      paste0("  <dir>", xml_escape(fonts), "</dir>"),
      paste0(
        "  <cachedir>",
        xml_escape(file.path(dir, "fontconfig-cache")),
        "</cachedir>"
      ),
      "</fontconfig>"
    ),
    conf
  )
  conf
}

xml_escape <- function(x) {
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  gsub(">", "&gt;", x, fixed = TRUE)
}

# Returns the file names of the pages, in the directory of `pdf`.
rasterize_pdf <- function(pdf, name, dpi) {
  # `filenames` is a format for sprintf(): page number and file extension
  prefix <- gsub("%", "%%", file.path(dirname(pdf), name), fixed = TRUE)
  pages <- callr::r(
    convert_pdf,
    args = list(pdf, paste0(prefix, "-page-%02d.%s"), dpi)
  )
  basename(pages)
}

# This function runs in a separate R process.
# Its environment is the global environment there,
# so it can only use other packages.
convert_pdf <- function(pdf, filenames, dpi) {
  pdftools::pdf_convert(
    pdf,
    format = "png",
    filenames = filenames,
    dpi = dpi,
    verbose = FALSE
  )
}

compare_png <- function(tolerance) {
  force(tolerance)
  function(old, new) {
    if (testthat::compare_file_binary(old, new)) {
      return(TRUE)
    }
    if (tolerance == 0) {
      return(FALSE)
    }
    old <- png::readPNG(old)
    new <- png::readPNG(new)
    if (!identical(dim(old), dim(new))) {
      return(FALSE)
    }
    differs <- old != new
    if (length(dim(differs)) == 3) {
      differs <- rowSums(differs, dims = 2) > 0
    }
    mean(differs) <= tolerance
  }
}

# The environment record is never compared
compare_true <- function(old, new) {
  TRUE
}

pdf_snapshot_environment <- function(pdf, fonts = NULL, system_fonts = FALSE) {
  info <- Sys.info()
  pandoc <- if (rmarkdown::pandoc_available()) {
    as.character(rmarkdown::pandoc_version())
  } else {
    NA_character_
  }
  packages <- c("pdftools", "rmarkdown", "knitr", "tinytex")
  files <- font_files(fonts)

  c(
    "# Toolchain used to generate the visual snapshots in this directory.",
    "# Pixel-exact comparisons are only stable on this toolchain; refreshed",
    "# only when the snapshots themselves are regenerated.",
    paste0("os: ", info[["sysname"]], " ", info[["release"]]),
    paste0("r: ", getRversion()),
    paste0("pandoc: ", pandoc),
    paste0("latex: ", latex_version(pdf)),
    paste0("poppler: ", pdftools::poppler_config()$version),
    paste0("fontconfig: ", fontconfig_version()),
    paste0("freetype: ", loaded_library("libfreetype")),
    paste0(packages, ": ", vapply(packages, package_version_or_na, "")),
    paste0("system fonts: ", if (system_fonts) "visible" else "hidden"),
    paste0("fc-match Helvetica: ", run_command("fc-match", "Helvetica")[1]),
    if (length(files) > 0) {
      paste0("font: ", files, " ", rlang::hash_file(file.path(fonts, files)))
    }
  )
}

pdf_producer <- function(pdf) {
  producer <- pdftools::pdf_info(pdf)$keys$Producer
  if (is.null(producer)) NA_character_ else producer
}

# The engine is inferred from the PDF producer that it writes
latex_engine <- function(producer) {
  if (is.na(producer)) {
    return(NULL)
  }
  if (grepl("xdvipdfmx", producer, ignore.case = TRUE)) {
    "xelatex"
  } else if (grepl("LuaTeX|LuaHBTeX", producer, ignore.case = TRUE)) {
    "lualatex"
  } else if (grepl("pdfTeX", producer, ignore.case = TRUE)) {
    "pdflatex"
  }
}

latex_version <- function(pdf) {
  producer <- pdf_producer(pdf)
  engine <- latex_engine(producer)
  if (is.null(engine)) {
    return(paste0("unknown, PDF producer: ", producer))
  }
  run_command(engine, "--version", stderr = TRUE)[1]
}

fontconfig_version <- function() {
  version <- run_command("fc-match", "--version", stderr = TRUE)[1]
  version <- sub("^fontconfig version ", "", version)
  paste0(version, " (", loaded_library("libfontconfig"), ")")
}

# The file name of a shared library loaded into this R process,
# with the full version number of the library
loaded_library <- function(lib, maps_file = "/proc/self/maps") {
  maps <- tryCatch(suppressWarnings(readLines(maps_file)), error = function(e) {
    character()
  })
  paths <- grep(paste0("/", lib, "[.]so"), maps, value = TRUE)
  if (length(paths) == 0) {
    return(NA_character_)
  }
  basename(sub("^.* ", "", paths[[1]]))
}

package_version_or_na <- function(package) {
  if (rlang::is_installed(package)) {
    as.character(utils::packageVersion(package))
  } else {
    NA_character_
  }
}

# The lines of the output of a command, or NA if it fails
run_command <- function(command, args, stderr = FALSE) {
  if (!nzchar(Sys.which(command))) {
    return(NA_character_)
  }
  out <- tryCatch(
    suppressWarnings(system2(command, args, stdout = TRUE, stderr = stderr)),
    error = function(e) NA_character_
  )
  if (length(out) == 0 || !is.null(attr(out, "status"))) {
    return(NA_character_)
  }
  out
}
